// Sound per-control ordered-tail interval may analysis. Count >=OMEGA becomes
// unbounded (not a guessed upper cap); joins are coordinatewise maxima.
#include <bits/stdc++.h>
using namespace std;struct E{int f,t,a,c;vector<int>I,O;};
int main(int ac,char**av){ifstream f(av[1]);int m,np,ne,ni,ng;f>>m>>np>>ne>>ni>>ng;int d=m*5;vector<int>initial(ni);for(auto&x:initial)f>>x;vector<pair<int,vector<int>>>goals;for(int j=0,p;j<ng;j++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals.push_back({p,r});}vector<E>es(ne);vector<vector<int>>adj(np);for(int j=0;j<ne;j++){auto&e=es[j];f>>e.f>>e.t>>e.a>>e.c;e.I.resize(d);e.O.resize(m);for(auto&x:e.I)f>>x;for(auto&x:e.O)f>>x;assert(f);adj[e.f].push_back(j);}int omega=ac>2?stoi(av[2]):8;assert(omega>0);string prefix=ac>3?av[3]:"interval";vector<vector<int>>V(np,vector<int>(d));vector<char>seen(np),queued(np);queue<int>q;for(int p:initial){seen[p]=queued[p]=1;q.push(p);}size_t pops=0,updates=0;
auto step=[&](const E&e,const vector<int>&x,vector<int>&y){for(int j=0;j<d;j++)if(x[j]!=omega&&x[j]<e.I[j])return false;for(int z=0;z<m;z++){int o=5*z;int a=x[o]==omega?omega:x[o]-e.I[o];int mn=a;for(int j=0;j<=e.c;j++)y[o+j]=a==omega?omega:min(omega,a+e.O[z]);for(int j=e.c+1;j<5;j++){int k=j-e.c,b=x[o+k]==omega?omega:x[o+k]-e.I[o+k];mn=min(mn,b);y[o+j]=mn;}}return true;};
while(!q.empty()){int p=q.front();q.pop();queued[p]=0;pops++;for(int ei:adj[p]){auto&e=es[ei];vector<int>y(d);if(!step(e,V[p],y))continue;bool changed=!seen[e.t];seen[e.t]=1;for(int j=0;j<d;j++)if(y[j]>V[e.t][j]){V[e.t][j]=y[j];changed=true;}if(changed){updates++;if(!queued[e.t]){queued[e.t]=1;q.push(e.t);}}}if(pops%100000==0)cerr<<"pops "<<pops<<" updates "<<updates<<" queue "<<q.size()<<"\n";}
vector<int>goodgoals,goodedges;for(int k=0;k<ng;k++){auto&[p,r]=goals[k];if(!seen[p])continue;bool ok=true;for(int j=0;j<d;j++)if(V[p][j]!=omega&&V[p][j]<r[j])ok=false;if(ok)goodgoals.push_back(k);}vector<int>tmp(d);for(int k=0;k<ne;k++)if(seen[es[k].f]&&step(es[k],V[es[k].f],tmp))goodedges.push_back(k);
cout<<"status "<<(goodgoals.empty()?"INTERVAL_NO_GOAL":"MAY_GOAL")<<" controls "<<count(seen.begin(),seen.end(),1)<<" edges "<<goodedges.size()<<" goals "<<goodgoals.size()<<" pops "<<pops<<" updates "<<updates<<" omega "<<omega<<"\n";
ofstream inv(prefix+".interval");inv<<m<<" "<<np<<" "<<omega<<"\n";for(int p=0;p<np;p++){inv<<p<<" "<<int(seen[p]);for(int x:V[p])inv<<" "<<x;inv<<"\n";}
ofstream out(prefix+".dat");out<<m<<" "<<np<<" "<<goodedges.size()<<" "<<ni<<" "<<goodgoals.size()<<"\n";for(int p:initial)out<<p<<" ";out<<"\n";for(int k:goodgoals){auto&[p,r]=goals[k];out<<p;for(int x:r)out<<" "<<x;out<<"\n";}for(int k:goodedges){auto&e=es[k];out<<e.f<<" "<<e.t<<" "<<e.a<<" "<<e.c;for(int x:e.I)out<<" "<<x;for(int x:e.O)out<<" "<<x;out<<"\n";}ofstream ids(prefix+".edge_ids");for(int k:goodedges)ids<<k<<"\n";
}
